    ga: `
এই মাদরাসার কুতুবখানায় একটি বই আছে। // فِي مَكْتَبَةِ هٰذِهِ الْمَدْرَسَةِ كِتَابٌ
মাদরাসার দফতরে কি কোন লোক আছে? | হাঁ, মাদরাসার দফতরে একজন লোক আছে। // هَلْ فِي مَكْتَبِ الْمَدْرَسَةِ رَجُلٌ؟ | نَعَمْ ، فِي مَكْتَبِ الْمَدْرَسَةِ رَجُلٌ
এই সৈনিকের বন্দুকটি ছোট। // بُنْدُقِيَّةُ هٰذَا الْجُنْدِيِّ صَغِيرَةٌ
মুমিনের অস্ত্র কী | এবং জান্নাতের চাবি কী? // مَا سِلَاحُ الْمُؤْمِنِ | وَمَا مِفْتَاحُ الْجَنَّةِ؟
অযু হলো মুমিনের অস্ত্র | এবং নামায হলো জান্নাতের চাবি। // اَلْوُضُوءُ سِلَاحُ الْمُؤْمِنِ | وَالصَّلَاةُ مِفْتَاحُ الْجَنَّةِ
মদীনার খেজুর খুব সুস্বাদু। // تَمْرُ الْمَدِينَةِ لَذِيذٌ جِدًّا
জমজমের পানি মক্কায় আছে। // مَاءُ زَمْزَمَ فِي مَكَّةَ
জমজমের পানি খুব বরকতপূর্ণ। // مَاءُ زَمْزَمَ مُبَارَكٌ جِدًّا
আল্লাহর ঘর কোথায়? | আল্লাহর ঘর মক্কায়। // أَيْنَ بَيْتُ اللّٰهِ؟ | بَيْتُ اللّٰهِ فِي مَكَّةَ
নবীর মসজিদ কোথায়? | নবীর মসজিদটি মদীনা মুনাওয়ারায়। // أَيْنَ مَسْجِدُ النَّبِيِّ؟ | مَسْجِدُ النَّبِيِّ فِي الْمَدِينَةِ الْمُنَوَّرَةِ
এই টেবিলের উপর একটি সুন্দর ঘড়ি আছে। // فَوْقَ هٰذِهِ الطَّاوِلَةِ سَاعَةٌ جَمِيلَةٌ
এটি টেবিলঘড়ি। // هٰذِهِ سَاعَةُ الطَّاوِلَةِ
টেবিলঘড়িটি এই টেবিলের উপর আছে। // سَاعَةُ الطَّاوِلَةِ فَوْقَ هٰذِهِ الطَّاوِلَةِ
আয়েশার গলায় কি কোন হার আছে? | হাঁ, তার গলায় একটি দামী হার আছে। // هَلْ فِي عُنُقِ عَائِشَةَ عِقْدٌ؟ | نَعَمْ ، فِي عُنُقِهَا عِقْدٌ غَالٍ
এই গ্রামের মাদরাসায় কি কোন মেধাবী ছাত্র আছে? | হাঁ, সেখানে একজন মেধাবী ছাত্র আছে। // هَلْ فِي مَدْرَسَةِ هٰذِهِ الْقَرْيَةِ تِلْمِيذٌ ذَكِيٌّ؟ | نَعَمْ ، فِيهَا تِلْمِيذٌ ذَكِيٌّ
দুধের পাত্রে কি দুধ আছে? | হাঁ, তাতে দুধ আছে। // هَلْ فِي إِنَاءِ اللَّبَنِ لَبَنٌ؟ | نَعَمْ ، فِيهِ لَبَنٌ
এই কামরার বাতিটি পুরোনো। // مِصْبَاحُ هٰذِهِ الْغُرْفَةِ قَدِيمٌ
তার আলো খুব দুর্বল। // ضَوْءُهُ ضَعِيفٌ جِدًّا
মুসলমান কি সাহসী? // هَلِ الْمُسْلِمُ شُجَاعٌ؟
সাহসী কি মুসলমান না মুনাফিক? // أَ الشُّجَاعُ مُسْلِمٌ أَمْ مُنَافِقٌ؟
এই লোকটির অন্তরে কি নেফাক আছে? // هَلْ فِي قَلْبِ هٰذَا الرَّجُلِ نِفَاقٌ؟
শিক্ষক কি ক্লাসরুমে আছেন? // هَلِ الْمُعَلِّمُ فِي الْفَصْلِ؟
হে মেয়ে! তোমার বাগানে একটি সুন্দর গাছ আছে। // يَا بِنْتُ ، فِي حَدِيقَتِكِ شَجَرَةٌ جَمِيلَةٌ
এটি গোলাবগাছ। // هٰذِهِ شَجَرَةُ الْوَرْدِ
একটি খেজুর। | খেজুরটি বড়। // تَمْرَةٌ | اَلتَّمْرَةُ كَبِيرَةٌ
খেজুর উত্তম খাদ্য। // اَلتَّمْرُ طَعَامٌ طَيِّبٌ
`
